"""Add annotation queues: lists of traces for people to score.

Revision ID: 0504
Revises: 0503
Create Date: 2026-10-10

A queue names the score configs a reviewer fills in and holds the traces (or spans) to review.
A reviewer claims the next pending item, scores it and completes it, or skips or releases it.

Choices worth knowing about:

* Ids are UUIDv7 generated by the application, so no column has a default.
* `annotation_queues` carries `project_id` and cascades from `projects`; `UNIQUE (project_id,
  name)` keeps names apart within a project.
* `score_config_ids` is a plain `uuid[]`, not a join table: a queue is small, its configs are
  read together, and they are checked against the project when the queue is created.
* `annotation_queue_items` has no `project_id`: it belongs to its queue and cascades from it. Its
  row-level security policy asks whether the queue is visible, so an item is exactly as visible
  as its queue. The policy uses the same InitPlan form as the project policies.
* `trace_id` and `span_id` are plain text, not foreign keys: traces are deleted by retention.
* A trace (or one of its spans) is queued once: the unique expression index treats a missing
  span as the empty string, because NULLs never collide in a plain unique index.
* `assigned_at` dates a claim, so a claim older than the claim timeout can be taken over.
* Indexes: `(queue_id, status, id)` serves claiming and the keyset listing; `assigned_to`,
  `completed_by` and `queues.created_by` are indexed so deleting a user does not scan the tables.

The migration creates new tables only, in one transaction. Downgrade drops them.
"""

from collections.abc import Sequence

from alembic import op

revision: str = "0504"
down_revision: str | None = "0503"
branch_labels: str | Sequence[str] | None = None
depends_on: str | Sequence[str] | None = None

PROJECT_EXPRESSION = (
    "project_id = (SELECT NULLIF(current_setting('app.project_id', true), '')::uuid)"
)
BYPASS_EXPRESSION = "(SELECT current_setting('app.bypass_rls', true)) = 'on'"
ITEM_EXPRESSION = (
    "EXISTS (SELECT 1 FROM annotation_queues q WHERE q.id = annotation_queue_items.queue_id)"
)


def upgrade() -> None:
    _create_tables()
    _enable_rls()


def _create_tables() -> None:
    op.execute(
        """
        CREATE TABLE annotation_queues (
            id                uuid PRIMARY KEY,
            project_id        uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
            name              text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100),
            instructions      text CHECK (char_length(instructions) <= 4000),
            score_config_ids  uuid[] NOT NULL
                              CHECK (cardinality(score_config_ids) BETWEEN 1 AND 20),
            created_by        uuid REFERENCES users (id) ON DELETE SET NULL,
            created_at        timestamptz NOT NULL DEFAULT now(),
            CONSTRAINT annotation_queues_project_name_key UNIQUE (project_id, name)
        )
        """
    )
    op.execute("CREATE INDEX annotation_queues_created_by_idx ON annotation_queues (created_by)")
    op.execute(
        """
        CREATE TABLE annotation_queue_items (
            id            uuid PRIMARY KEY,
            queue_id      uuid NOT NULL REFERENCES annotation_queues (id) ON DELETE CASCADE,
            trace_id      text NOT NULL,
            span_id       text,
            status        text NOT NULL DEFAULT 'pending'
                          CHECK (status IN ('pending', 'done', 'skipped')),
            assigned_to   uuid REFERENCES users (id) ON DELETE SET NULL,
            assigned_at   timestamptz,
            completed_by  uuid REFERENCES users (id) ON DELETE SET NULL,
            completed_at  timestamptz,
            created_at    timestamptz NOT NULL DEFAULT now()
        )
        """
    )
    op.execute(
        "CREATE INDEX annotation_queue_items_queue_status_idx "
        "ON annotation_queue_items (queue_id, status, id)"
    )
    op.execute(
        "CREATE INDEX annotation_queue_items_assigned_to_idx "
        "ON annotation_queue_items (assigned_to)"
    )
    op.execute(
        "CREATE INDEX annotation_queue_items_completed_by_idx "
        "ON annotation_queue_items (completed_by)"
    )
    op.execute(
        "CREATE UNIQUE INDEX annotation_queue_items_target_key "
        "ON annotation_queue_items (queue_id, trace_id, coalesce(span_id, ''))"
    )


def _enable_rls() -> None:
    op.execute("ALTER TABLE annotation_queues ENABLE ROW LEVEL SECURITY")
    op.execute("ALTER TABLE annotation_queues FORCE ROW LEVEL SECURITY")
    op.execute(
        "CREATE POLICY annotation_queues_project_isolation ON annotation_queues "
        f"USING ({PROJECT_EXPRESSION}) WITH CHECK ({PROJECT_EXPRESSION})"
    )
    op.execute(
        "CREATE POLICY annotation_queues_worker_bypass ON annotation_queues "
        f"USING ({BYPASS_EXPRESSION}) WITH CHECK ({BYPASS_EXPRESSION})"
    )
    op.execute("ALTER TABLE annotation_queue_items ENABLE ROW LEVEL SECURITY")
    op.execute("ALTER TABLE annotation_queue_items FORCE ROW LEVEL SECURITY")
    op.execute(
        "CREATE POLICY annotation_queue_items_project_isolation ON annotation_queue_items "
        f"USING ({ITEM_EXPRESSION}) WITH CHECK ({ITEM_EXPRESSION})"
    )
    op.execute(
        "CREATE POLICY annotation_queue_items_worker_bypass ON annotation_queue_items "
        f"USING ({BYPASS_EXPRESSION}) WITH CHECK ({BYPASS_EXPRESSION})"
    )


def downgrade() -> None:
    op.execute("DROP TABLE IF EXISTS annotation_queue_items")
    op.execute("DROP TABLE IF EXISTS annotation_queues")
